/* Nikhat School ERP — clean final application foundation. No legacy V159 sync code. */
const SCHOOL={name:'NIKHAT MIDDLE SCHOOL DIGORA',dise:'23080208912',address:'Near of Jain Mandir, Ward No. 04, Digoar, Tikamgarh, Madhya Pradesh'};
const ROLES={admin:'Admin',principal:'Principal',accountant:'Accountant',office:'Office Assistant',teacher:'Teacher/Staff',parent:'Student/Parent'};
const ROLE_RULES={
 admin:'*',principal:'*',accountant:'*',
 office:['Dashboard','Students','Teachers & Staff','Classes & Sections','Attendance','Exams & Marks','Report Card','Certificates','ID Cards','Timetable','Homework / Assignment','Communication','Parent Contacts','Settings'],
 teacher:['Dashboard','Classes & Sections','Attendance','Exams & Marks','Report Card','Timetable','Homework / Assignment','Communication'],
 parent:['Dashboard','Student Portal']
};
const STORE={students:[],staff:[],classes:[],attendance:[],exams:[],marks:[],certificates:[],ids:[],timetable:[],homework:[],notices:[],parents:[],promotions:[],users:[],fees:[],feeVoids:[],audit:[],settings:{session:'2026-27',school:SCHOOL},cloud:{url:'',key:'',lastSync:null,status:'Not configured'}};
const DBKEY='nikhat_erp_final_v1_data';
let db=loadDB(); let currentUser=loadSession(); let currentPage='Dashboard'; let editing=null;
function clone(x){return JSON.parse(JSON.stringify(x))} function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function uid(prefix='id'){return prefix+'_'+crypto.randomUUID().replaceAll('-','').slice(0,20)}
function loadDB(){try{return Object.assign(clone(STORE),JSON.parse(localStorage.getItem(DBKEY)||'{}'))}catch{return clone(STORE)}}
function saveDB(){localStorage.setItem(DBKEY,JSON.stringify(db)); updateCloudStatus();}
function loadSession(){try{return JSON.parse(sessionStorage.getItem('nikhat_user')||localStorage.getItem('nikhat_user')||'null')}catch{return null}}
function saveSession(u,remember){const v=JSON.stringify(u);sessionStorage.setItem('nikhat_user',v);if(remember)localStorage.setItem('nikhat_user',v)}
function logout(){sessionStorage.removeItem('nikhat_user');localStorage.removeItem('nikhat_user');currentUser=null;currentPage='Dashboard';render()}
function toast(msg){const t=document.getElementById('toast');t.innerHTML='<div class="toast">'+esc(msg)+'</div>';setTimeout(()=>t.innerHTML='',2800)}
function allowed(page){const r=currentUser?.role;const rules=ROLE_RULES[r];return rules==='*'||rules?.includes(page)}
function navItems(){return ['Dashboard','Students','Teachers & Staff','Classes & Sections','Attendance','Fees','Exams & Marks','Report Card','Certificates','ID Cards','Timetable','Homework / Assignment','Communication','Parent Contacts','Reports','Promotion','Users & Permissions','Central Database','Backup & Restore','System Health','Settings'].filter(allowed)}
function schoolHeader(sub='School Management ERP'){return `<div class="brand"><img src="./logo.jpg"><div><div class="brand-title">${SCHOOL.name}</div><div class="brand-sub">DISE Code – ${SCHOOL.dise} • ${esc(sub)}</div></div></div>`}
function loginView(){document.getElementById('app').innerHTML=`<main class="login"><section class="login-card"><img class="logo" src="./logo.jpg"><div class="school-name">${SCHOOL.name}</div><div class="school-meta"><b>DISE Code – ${SCHOOL.dise}</b><br>${SCHOOL.address}</div><form id="loginForm"><div class="field"><label>School Login ID</label><input id="loginId" autocomplete="username" required placeholder="Enter login ID"></div><div class="field"><label>Password</label><input id="loginPw" type="password" autocomplete="current-password" required placeholder="Enter password"></div><label style="display:flex;gap:7px;align-items:center;justify-content:flex-start;font-size:12px"><input id="remember" type="checkbox"> Remember this device</label><button class="btn primary" style="width:100%;margin-top:14px">Login</button></form><div class="hint">School login • Offline-first • Cloud sync is designed as a separate secure layer.</div><div class="hint">Initial local administrator: <b>admin</b> / <b>1234</b></div></section></main>`;
 document.getElementById('loginForm').onsubmit=e=>{e.preventDefault();const id=document.getElementById('loginId').value.trim().toLowerCase(),pw=document.getElementById('loginPw').value;const built={admin:'admin',principal:'principal',accountant:'accountant',office:'office',teacher:'teacher',parent:'student'};let role=Object.keys(built).find(k=>built[k]===id);const custom=db.users.find(u=>u.username?.toLowerCase()===id&&u.active!==false);if(custom&&pw===custom.password)role=custom.role;if(!role||pw!=='1234'&&!custom)return toast('Invalid login ID or password');currentUser={id,role,name:custom?.name||ROLES[role]};saveSession(currentUser,document.getElementById('remember').checked);render()}}
function render(){if(!currentUser)return loginView();if(currentUser.role==='parent')return portal();if(!allowed(currentPage))currentPage='Dashboard';document.getElementById('app').innerHTML=layout();renderPage()}
function layout(){return `<div class="shell"><header class="top">${schoolHeader(ROLES[currentUser.role])}<div class="actions"><span class="tag" style="background:#fff;color:#0b2148">${esc(currentUser.name||ROLES[currentUser.role])}</span><button class="btn gold small" onclick="logout()">Logout</button></div></header><div class="layout"><aside class="side"><div class="nav-section">Navigation</div>${navItems().map(x=>`<button class="nav ${x===currentPage?'active':''}" data-nav="${esc(x)}">${esc(x)}</button>`).join('')}</aside><main class="main" id="page"></main></div></div>`}
function bindNav(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{currentPage=b.dataset.nav;render()})}
function renderPage(){bindNav();const f={Dashboard:dashboard,Students:studentsPage,'Teachers & Staff':staffPage,'Classes & Sections':classesPage,Attendance:attendancePage,Fees:feesPage,'Exams & Marks':examsPage,'Report Card':reportCardPage,Certificates:certificatesPage,'ID Cards':idsPage,Timetable:timetablePage,'Homework / Assignment':homeworkPage,Communication:communicationPage,'Parent Contacts':parentsPage,Reports:reportsPage,Promotion:promotionPage,'Users & Permissions':usersPage,'Central Database':cloudPage,'Backup & Restore':backupPage,'System Health':healthPage,Settings:settingsPage}[currentPage];f?.()}
function pageHead(title,desc='',buttons=''){return `<div class="page-head"><div><h2>${esc(title)}</h2>${desc?`<div class="muted" style="margin-top:4px;font-size:12px">${esc(desc)}</div>`:''}</div><div class="actions">${buttons}</div></div>`}
function table(rows,heads){if(!rows.length)return `<div class="empty">No records yet.</div>`;return `<div class="table-wrap"><table class="table"><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function dashboard(){const p=document.getElementById('page');const due=feeBalanceAll();p.innerHTML=`<div class="welcome"><span class="tag">${ROLES[currentUser.role]}</span><h1>School Dashboard</h1><div class="muted">${SCHOOL.address}</div></div><div class="grid"><div class="stat">Students<b>${db.students.length}</b><span class="muted">Active: ${db.students.filter(s=>s.status!=='left').length}</span></div><div class="stat">Teachers & Staff<b>${db.staff.length}</b><span class="muted">Active staff records</span></div><div class="stat">Attendance Records<b>${db.attendance.length}</b><span class="muted">All sessions</span></div><div class="stat">Total Due<b>₹${money(due.due)}</b><span class="muted">Paid ₹${money(due.paid)}</span></div></div><div class="card" style="margin-top:15px"><h3 style="margin-top:0">School Identity</h3><div style="display:flex;gap:15px;align-items:center"><img src="./logo.jpg" style="width:85px;height:85px;object-fit:contain"><div><b>${SCHOOL.name}</b><br><span class="muted">DISE Code – ${SCHOOL.dise}<br>${SCHOOL.address}</span></div></div></div><h3 class="section-title">Available Modules</h3><div class="modules">${navItems().filter(x=>x!=='Dashboard').map(x=>`<article class="module" onclick="currentPage='${x.replaceAll("'","\\'")}';render()"><h3>${esc(x)}</h3><p>Open ${esc(x)} module</p></article>`).join('')}</div>`}
function modal(title,body){document.getElementById('toast').insertAdjacentHTML('beforebegin',`<div class="modal-back" id="modal"><div class="modal"><div class="modal-head"><h3>${esc(title)}</h3><button class="btn light small" onclick="closeModal()">Close</button></div><div style="margin-top:14px">${body}</div></div></div>`)}
function closeModal(){document.getElementById('modal')?.remove()}
function money(n){return Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:2})}
function csvDownload(filename,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=filename;a.click();URL.revokeObjectURL(a.href)}
function csvUpload(input,cb){const file=input.files[0];if(!file)return;const rd=new FileReader();rd.onload=()=>{const lines=String(rd.result).split(/\r?\n/).filter(Boolean);const out=lines.map(line=>{const r=[];let q=false,s='',i=0;for(;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){s+='"';i++}else q=!q}else if(c===','&&!q){r.push(s);s=''}else s+=c}r.push(s);return r});cb(out.slice(1),out[0])};rd.readAsText(file)}
function studentForm(s={}){return `<form id="studentForm"><div class="form-grid"><div><label>Name</label><input name="name" required value="${esc(s.name)}"></div><div><label>Admission No.</label><input name="admission_no" required value="${esc(s.admission_no)}"></div><div><label>Roll No.</label><input name="roll_no" value="${esc(s.roll_no)}"></div><div><label>DOB</label><input type="date" name="dob" value="${esc(s.dob)}"></div><div><label>Father's Name</label><input name="father" value="${esc(s.father)}"></div><div><label>Mother's Name</label><input name="mother" value="${esc(s.mother)}"></div><div><label>Guardian Mobile</label><input name="mobile" value="${esc(s.mobile)}"></div><div><label>Class</label><input name="class_name" value="${esc(s.class_name)}"></div><div><label>Section</label><input name="section" value="${esc(s.section)}"></div><div><label>Samagra ID</label><input name="samagra" value="${esc(s.samagra)}"></div><div><label>Aadhaar</label><input name="aadhaar" value="${esc(s.aadhaar)}"></div><div><label>Admission Date</label><input type="date" name="admission_date" value="${esc(s.admission_date)}"></div><div><label>Category</label><input name="category" value="${esc(s.category)}"></div><div><label>Status</label><select name="status"><option ${s.status==='active'||!s.status?'selected':''}>active</option><option ${s.status==='inactive'?'selected':''}>inactive</option><option ${s.status==='left'?'selected':''}>left</option></select></div><div class="wide"><label>Previous School</label><input name="previous_school" value="${esc(s.previous_school)}"></div></div><div class="form-actions"><button class="btn primary">Save Student</button></div></form>`}
function studentsPage(){const p=document.getElementById('page');let q='';const draw=()=>{const list=db.students.filter(s=>[s.name,s.admission_no,s.class_name,s.section,s.mobile].join(' ').toLowerCase().includes(q.toLowerCase()));p.innerHTML=pageHead('Students','Admission, profile, search, bulk import/export and academic history',`<button class="btn primary" id="add">+ Add Student</button><button class="btn light" id="export">Export CSV</button><label class="btn light">Import CSV<input id="imp" type="file" accept=".csv" hidden></label>`)+`<div class="card"><div class="searchbar"><input id="sq" placeholder="Search name / admission / class / mobile" value="${esc(q)}"><select id="sc"><option value="">All Classes</option>${[...new Set(db.students.map(s=>s.class_name).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div>${table(list.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.admission_no)}</td><td>${esc(s.class_name)}-${esc(s.section)}</td><td>${esc(s.roll_no)}</td><td>${esc(s.mobile)}</td><td><button class="btn small light" onclick="editStudent('${s.id}')">Edit</button> <button class="btn small danger" onclick="deleteStudent('${s.id}')">Delete</button></td></tr>`),['Name','Admission No.','Class','Roll','Mobile','Action'])}</div>`;document.getElementById('sq').oninput=e=>{q=e.target.value;draw()};document.getElementById('sc').onchange=e=>{const v=e.target.value;const base=list;const x=v?base.filter(s=>s.class_name===v):base;p.querySelector('tbody')?.replaceChildren(...x.map(s=>{const tr=document.createElement('tr');tr.innerHTML=`<td>${esc(s.name)}</td><td>${esc(s.admission_no)}</td><td>${esc(s.class_name)}-${esc(s.section)}</td><td>${esc(s.roll_no)}</td><td>${esc(s.mobile)}</td><td><button class="btn small light" onclick="editStudent('${s.id}')">Edit</button> <button class="btn small danger" onclick="deleteStudent('${s.id}')">Delete</button></td>`;return tr}))};document.getElementById('add').onclick=()=>{modal('Add Student',studentForm());document.getElementById('studentForm').onsubmit=saveStudent};document.getElementById('export').onclick=()=>csvDownload('students.csv',[['Name','Admission No','Roll No','DOB','Father','Mother','Mobile','Class','Section','Samagra','Aadhaar','Admission Date','Category','Status'],...db.students.map(s=>[s.name,s.admission_no,s.roll_no,s.dob,s.father,s.mother,s.mobile,s.class_name,s.section,s.samagra,s.aadhaar,s.admission_date,s.category,s.status])]);document.getElementById('imp').onchange=e=>csvUpload(e,rows=>{let ok=0;rows.forEach(r=>{if(!r[0]||!r[1])return;if(db.students.some(s=>s.admission_no===r[1]))return;db.students.push({id:uid('stu'),name:r[0],admission_no:r[1],roll_no:r[2],dob:r[3],father:r[4],mother:r[5],mobile:r[6],class_name:r[7],section:r[8],samagra:r[9],aadhaar:r[10],admission_date:r[11],category:r[12],status:r[13]||'active',created_at:new Date().toISOString()});ok++});saveDB();toast(`${ok} students imported`);draw()})};draw()}
function saveStudent(e){e.preventDefault();const f=new FormData(e.target),o=Object.fromEntries(f);if(!editing&&db.students.some(s=>s.admission_no===o.admission_no))return toast('Duplicate admission number');const id=editing?.id||uid('stu');const old=db.students.find(s=>s.id===id);const rec={id,...o,created_at:old?.created_at||new Date().toISOString(),updated_at:new Date().toISOString()};if(old)Object.assign(old,rec);else db.students.push(rec);audit('student',id,old,rec,'save');saveDB();editing=null;closeModal();toast('Student saved');studentsPage()}
function editStudent(id){editing=db.students.find(s=>s.id===id);modal('Edit Student',studentForm(editing));document.getElementById('studentForm').onsubmit=saveStudent}
function deleteStudent(id){if(!confirm('Delete this student?'))return;const s=db.students.find(x=>x.id===id);if(!s)return;s.status='left';s.updated_at=new Date().toISOString();audit('student',id,s,null,'soft-delete');saveDB();toast('Student marked left');studentsPage()}
function staffForm(s={}){return `<form id="staffForm"><div class="form-grid"><div><label>Name</label><input name="name" required value="${esc(s.name)}"></div><div><label>Employee ID</label><input name="employee_id" required value="${esc(s.employee_id)}"></div><div><label>Designation</label><input name="designation" value="${esc(s.designation)}"></div><div><label>Subject</label><input name="subject" value="${esc(s.subject)}"></div><div><label>Mobile</label><input name="mobile" value="${esc(s.mobile)}"></div><div><label>Joining Date</label><input type="date" name="joining" value="${esc(s.joining)}"></div><div><label>Username</label><input name="username" value="${esc(s.username)}"></div><div><label>Password</label><input name="password" value="${esc(s.password||'1234')}"></div><div><label>Role</label><select name="role"><option value="teacher">Teacher/Staff</option><option value="office">Office Assistant</option><option value="accountant">Accountant</option><option value="principal">Principal</option></select></div><div><label>Status</label><select name="status"><option>active</option><option>inactive</option></select></div></div><div class="form-actions"><button class="btn primary">Save Staff</button></div></form>`}
function staffPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Teachers & Staff','Profiles, employee IDs, credentials, import/export',`<button class="btn primary" onclick="modal('Add Teacher/Staff',staffForm());document.getElementById('staffForm').onsubmit=saveStaff">+ Add Staff</button><button class="btn light" onclick="exportStaff()">Export CSV</button>`)+`<div class="card">${table(db.staff.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.employee_id)}</td><td>${esc(s.designation)}</td><td>${esc(s.subject)}</td><td>${esc(s.mobile)}</td><td>${esc(s.username||'—')}</td><td><button class="btn small light" onclick="editStaff('${s.id}')">Edit</button> <button class="btn small danger" onclick="removeStaff('${s.id}')">Delete</button></td></tr>`),['Name','Employee ID','Designation','Subject','Mobile','Login ID','Action'])}</div>`}
function saveStaff(e){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(db.staff.some(s=>s.employee_id===o.employee_id&&s.id!==editing?.id))return toast('Duplicate Employee ID');const id=editing?.id||uid('stf');const old=db.staff.find(s=>s.id===id);const rec={id,...o,created_at:old?.created_at||new Date().toISOString()};if(old)Object.assign(old,rec);else db.staff.push(rec);if(o.username){const u=db.users.find(x=>x.username===o.username);if(u)Object.assign(u,{name:o.name,password:o.password,role:o.role,active:o.status==='active'});else db.users.push({id:uid('usr'),username:o.username,password:o.password||'1234',name:o.name,role:o.role,active:true})}audit('staff',id,old,rec,'save');saveDB();editing=null;closeModal();toast('Staff saved');staffPage()}
function editStaff(id){editing=db.staff.find(s=>s.id===id);modal('Edit Staff',staffForm(editing));document.getElementById('staffForm').onsubmit=saveStaff}
function removeStaff(id){if(!confirm('Delete staff record?'))return;const s=db.staff.find(x=>x.id===id);s.status='inactive';saveDB();toast('Staff disabled');staffPage()}
function exportStaff(){csvDownload('staff.csv',[['Name','Employee ID','Designation','Subject','Mobile','Joining','Username','Role','Status'],...db.staff.map(s=>[s.name,s.employee_id,s.designation,s.subject,s.mobile,s.joining,s.username,s.role,s.status])])}
function classesPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Classes & Sections','Configurable academic session, classes, sections and subjects',`<button class="btn primary" onclick="addClass()">+ Add Class</button>`)+`<div class="card">${table(db.classes.map(c=>`<tr><td>${esc(c.session)}</td><td>${esc(c.name)}</td><td>${esc(c.section||'A')}</td><td>${esc(c.subjects||'')}</td><td><button class="btn small danger" onclick="removeClass('${c.id}')">Delete</button></td></tr>`),['Session','Class','Section','Subjects','Action'])}</div>`}
function addClass(){modal('Add Class / Section',`<form id="classForm"><div class="form-grid"><div><label>Session</label><input name="session" value="${esc(db.settings.session)}" required></div><div><label>Class</label><input name="name" required placeholder="LKG / 1 / 10"></div><div><label>Section</label><input name="section" value="A"></div><div class="wide"><label>Subjects (comma separated)</label><input name="subjects" placeholder="Hindi, English, Math"></div></div><div class="form-actions"><button class="btn primary">Save</button></div></form>`);document.getElementById('classForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(db.classes.some(c=>c.session===o.session&&c.name===o.name&&c.section===o.section))return toast('Class/section already exists');db.classes.push({id:uid('cls'),...o});saveDB();closeModal();classesPage()}}
function removeClass(id){if(confirm('Delete class/section?')){db.classes=db.classes.filter(x=>x.id!==id);saveDB();classesPage()}}
function attendancePage(){const p=document.getElementById('page');const cls=[...new Set(db.students.map(s=>`${s.class_name}|${s.section}`))];p.innerHTML=pageHead('Attendance','Any authorized teacher can select any class and take attendance',`<button class="btn primary" onclick="takeAttendance()">+ Take Attendance</button><button class="btn light" onclick="csvDownload('attendance.csv',[['Date','Student','Admission','Class','Status'],...db.attendance.map(a=>{const s=db.students.find(x=>x.id===a.student_id)||{};return[a.date,s.name,s.admission_no,s.class_name+'-'+s.section,a.status]})])">Export CSV</button>`)+`<div class="card"><div class="fee-big"><div class="fee-box"><span class="muted">Records</span><b>${db.attendance.length}</b></div><div class="fee-box"><span class="muted">Present</span><b>${db.attendance.filter(a=>a.status==='Present').length}</b></div><div class="fee-box"><span class="muted">Absent</span><b>${db.attendance.filter(a=>a.status==='Absent').length}</b></div><div class="fee-box"><span class="muted">Leave</span><b>${db.attendance.filter(a=>a.status==='Leave').length}</b></div></div></div><div class="card">${table(db.attendance.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,100).map(a=>{const s=db.students.find(x=>x.id===a.student_id)||{};return `<tr><td>${esc(a.date)}</td><td>${esc(s.name)}</td><td>${esc(s.class_name)}-${esc(s.section)}</td><td><span class="pill ${a.status==='Present'?'ok':'danger'}">${esc(a.status)}</span></td><td>${esc(a.subject||'')}</td></tr>`}),['Date','Student','Class','Status','Subject'])}</div>`}
function takeAttendance(){const date=new Date().toISOString().slice(0,10);const cls=[...new Set(db.students.map(s=>s.class_name).filter(Boolean))];modal('Take Attendance',`<form id="attForm"><div class="form-grid"><div><label>Date</label><input name="date" type="date" value="${date}"></div><div><label>Class</label><select id="attClass" name="class_name"><option value="">Select</option>${cls.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div><label>Section</label><input name="section" placeholder="A"></div><div><label>Subject</label><input name="subject"></div></div><div id="attList" class="card" style="margin-top:12px"></div><div class="form-actions"><button class="btn primary">Save Attendance</button></div></form>`);const draw=()=>{const c=document.querySelector('#attClass').value,sec=document.querySelector('[name=section]').value;const list=db.students.filter(s=>s.class_name===c&&(!sec||s.section===sec));document.getElementById('attList').innerHTML=list.length?list.map(s=>`<div style="display:grid;grid-template-columns:1fr 140px;gap:10px;align-items:center;padding:7px 0;border-bottom:1px solid var(--line)"><span>${esc(s.name)} <small class="muted">${esc(s.admission_no)}</small></span><select data-sid="${s.id}"><option>Present</option><option>Absent</option><option>Leave</option></select></div>`).join(''):'<div class="empty">Select class.</div>'};document.getElementById('attClass').onchange=draw;document.querySelector('[name=section]').oninput=draw;document.getElementById('attForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));document.querySelectorAll('#attList select').forEach(sel=>{db.attendance.push({id:uid('att'),date:o.date,student_id:sel.dataset.sid,status:sel.value,subject:o.subject,created_by:currentUser.id})});saveDB();closeModal();toast('Attendance saved');attendancePage()}}
function feesPage(){const p=document.getElementById('page');const bal=feeBalanceAll();p.innerHTML=pageHead('Fees','Transaction-based fee collection, receipts, ledgers, due and paid reports',`<button class="btn primary" onclick="collectFee()">+ Collect Fee</button><button class="btn light" onclick="feeLedger()">Student Ledger</button><button class="btn light" onclick="feeReport()">Collection Report</button>`)+`<div class="fee-big"><div class="fee-box"><span class="muted">Previous Due</span><b>₹${money(bal.previous)}</b></div><div class="fee-box"><span class="muted">Current Due</span><b>₹${money(bal.current)}</b></div><div class="fee-box"><span class="muted">Total Due</span><b>₹${money(bal.due)}</b></div><div class="fee-box"><span class="muted">Total Paid</span><b>₹${money(bal.paid)}</b></div></div><div class="card" style="margin-top:15px"><h3 style="margin-top:0">Fee Transactions</h3>${table(db.fees.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(t=>{const s=db.students.find(x=>x.id===t.student_id)||{};return `<tr><td>${esc(t.date)}</td><td>${esc(s.name)}</td><td>${esc(s.admission_no)}</td><td>${esc(t.receipt_no)}</td><td>₹${money(t.amount)}</td><td>${esc(t.mode)}</td><td><button class="btn small light" onclick="printReceipt('${t.id}')">Receipt</button> <button class="btn small danger" onclick="voidFee('${t.id}')">Reset/Delete</button></td></tr>`}),['Date','Student','Admission','Receipt No.','Amount','Mode','Action'])}</div>`}
function feeBalance(studentId){const s=db.students.find(x=>x.id===studentId);const prev=Number(s?.previous_due||0),cur=Number(s?.current_fee||0);const tx=db.fees.filter(t=>t.student_id===studentId&&t.status!=='void');const pp=tx.filter(t=>t.bucket==='previous').reduce((a,t)=>a+Number(t.amount||0),0),cp=tx.filter(t=>t.bucket==='current').reduce((a,t)=>a+Number(t.amount||0),0);return {previous:Math.max(0,prev-pp),current:Math.max(0,cur-cp),due:Math.max(0,prev-pp)+Math.max(0,cur-cp),paid:tx.reduce((a,t)=>a+Number(t.amount||0),0),previousPaid:pp,currentPaid:cp}}
function feeBalanceAll(){return db.students.reduce((a,s)=>{const b=feeBalance(s.id);a.previous+=b.previous;a.current+=b.current;a.due+=b.due;a.paid+=b.paid;return a},{previous:0,current:0,due:0,paid:0})}
function collectFee(){const opts=db.students.map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.admission_no)}</option>`).join('');modal('Collect Fee',`<form id="feeForm"><div class="form-grid"><div class="wide"><label>Student</label><select name="student_id" required>${opts}</select></div><div><label>Receipt No.</label><input name="receipt_no" required value="R-${new Date().getTime().toString().slice(-8)}"></div><div><label>Date</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div><label>Amount</label><input name="amount" type="number" min="1" required></div><div><label>Payment Mode</label><select name="mode"><option>Cash</option><option>UPI</option><option>Bank</option><option>Cheque</option></select></div><div><label>Allocation</label><select name="bucket"><option value="previous">Previous Due</option><option value="current">Current Fee</option></select></div><div class="wide"><label>Note</label><input name="note"></div></div><div id="feeHint" class="card" style="margin-top:12px"></div><div class="form-actions"><button class="btn primary">Save & Generate Receipt</button></div></form>`);const update=()=>{const b=feeBalance(document.querySelector('[name=student_id]').value);document.getElementById('feeHint').innerHTML=`Previous Due: <b>₹${money(b.previous)}</b> &nbsp; Current Due: <b>₹${money(b.current)}</b> &nbsp; Total: <b>₹${money(b.due)}</b>`};document.querySelector('[name=student_id]').onchange=update;update();document.getElementById('feeForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(db.fees.some(t=>t.receipt_no===o.receipt_no&&t.status!=='void'))return toast('Duplicate receipt number');const amount=Number(o.amount);const b=feeBalance(o.student_id);if((o.bucket==='previous'?b.previous:b.current)<amount)return toast('Amount is greater than selected due');const t={id:uid('fee'),...o,amount,status:'posted',created_by:currentUser.id,created_at:new Date().toISOString()};db.fees.push(t);audit('fee',t.id,null,t,'collect');saveDB();closeModal();toast('Fee collected and receipt created');feesPage()}}
function voidFee(id){if(!confirm('Reset/Delete this fee entry? It will be VOIDED and kept in audit history.'))return;const t=db.fees.find(x=>x.id===id);if(!t)return;t.status='void';t.voided_at=new Date().toISOString();t.voided_by=currentUser.id;db.feeVoids.push({id:uid('void'),fee_id:id,reason:'User correction',created_at:new Date().toISOString(),created_by:currentUser.id});audit('fee',id,t,null,'void');saveDB();toast('Fee entry voided');feesPage()}
function feeLedger(){modal('Student Fee Ledger',`<div class="searchbar"><select id="ledgerStudent"><option value="">Select student</option>${db.students.map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.admission_no)}</option>`).join('')}</select></div><div id="ledgerOut" class="card"><div class="empty">Select a student.</div></div>`);document.getElementById('ledgerStudent').onchange=e=>{const sid=e.target.value,s=db.students.find(x=>x.id===sid),b=feeBalance(sid);const tx=db.fees.filter(t=>t.student_id===sid).sort((a,c)=>c.date.localeCompare(a.date));document.getElementById('ledgerOut').innerHTML=`<div class="fee-big"><div class="fee-box">Previous Due<b>₹${money(b.previous)}</b></div><div class="fee-box">Current Due<b>₹${money(b.current)}</b></div><div class="fee-box">Total Due<b>₹${money(b.due)}</b></div><div class="fee-box">Paid<b>₹${money(b.paid)}</b></div></div><h4>${esc(s.name)} — ${esc(s.admission_no)}</h4>${table(tx.map(t=>`<tr><td>${esc(t.date)}</td><td>${esc(t.receipt_no)}</td><td>₹${money(t.amount)}</td><td>${esc(t.mode)}</td><td>${esc(t.bucket)}</td><td>${t.status==='void'?'<span class="pill danger">VOID</span>':'<span class="pill ok">POSTED</span>'}</td></tr>`),['Date','Receipt','Amount','Mode','Allocation','Status'])}`}}
function feeReport(){modal('Fee Collection Report',`<div class="actions"><button class="btn light" onclick="print()">Print</button><button class="btn light" onclick="csvDownload('fee-ledger.csv',[['Date','Student','Admission','Receipt','Amount','Mode','Allocation','Status'],...db.fees.map(t=>{const s=db.students.find(x=>x.id===t.student_id)||{};return[t.date,s.name,s.admission_no,t.receipt_no,t.amount,t.mode,t.bucket,t.status]})])">CSV</button></div><div class="card">${table(db.fees.map(t=>{const s=db.students.find(x=>x.id===t.student_id)||{};return `<tr><td>${esc(t.date)}</td><td>${esc(s.name)}</td><td>${esc(t.receipt_no)}</td><td>₹${money(t.amount)}</td><td>${esc(t.mode)}</td><td>${esc(t.bucket)}</td><td>${esc(t.status)}</td></tr>`}),['Date','Student','Receipt','Amount','Mode','Allocation','Status'])}</div>`) }
function printReceipt(id){const t=db.fees.find(x=>x.id===id),s=db.students.find(x=>x.id===t.student_id)||{};modal('Fee Receipt',`<div id="receipt" style="border:1px solid #ccc;padding:24px;max-width:650px;margin:auto;text-align:center"><img src="./logo.jpg" style="width:80px"><h2 style="margin:8px 0">${SCHOOL.name}</h2><b>DISE Code – ${SCHOOL.dise}</b><p>${SCHOOL.address}</p><hr><h3>FEE RECEIPT</h3><div style="text-align:left;line-height:2"><b>Receipt No.:</b> ${esc(t.receipt_no)}<br><b>Date:</b> ${esc(t.date)}<br><b>Student:</b> ${esc(s.name)}<br><b>Admission No.:</b> ${esc(s.admission_no)}<br><b>Class:</b> ${esc(s.class_name)}-${esc(s.section)}<br><b>Amount:</b> ₹${money(t.amount)}<br><b>Payment Mode:</b> ${esc(t.mode)}<br><b>Allocation:</b> ${esc(t.bucket)}<br><b>Note:</b> ${esc(t.note)}</div></div><div class="form-actions"><button class="btn primary" onclick="print()">Print Receipt</button></div>`)}
function examsPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Exams & Marks','Monthly Test, Quarterly, Half-Yearly, Annual and Consolidated',`<button class="btn primary" onclick="addExam()">+ Add Exam</button><button class="btn light" onclick="marksEntry()">Enter Marks</button>`)+`<div class="card">${table(db.exams.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.session)}</td><td>${esc(x.class_name)}</td><td>${esc(x.date)}</td><td><button class="btn small danger" onclick="deleteExam('${x.id}')">Delete</button></td></tr>`),['Exam','Session','Class','Date','Action'])}</div>`}
function addExam(){modal('Create Exam',`<form id="examForm"><div class="form-grid"><div><label>Exam</label><select name="name"><option>Monthly Test</option><option>Quarterly</option><option>Half-Yearly</option><option>Annual</option><option>Custom</option></select></div><div><label>Session</label><input name="session" value="${esc(db.settings.session)}"></div><div><label>Class</label><input name="class_name"></div><div><label>Date</label><input type="date" name="date"></div></div><div class="form-actions"><button class="btn primary">Save Exam</button></div></form>`);document.getElementById('examForm').onsubmit=e=>{e.preventDefault();db.exams.push({id:uid('exam'),...Object.fromEntries(new FormData(e.target))});saveDB();closeModal();examsPage()}}
function deleteExam(id){if(confirm('Delete exam?')){db.exams=db.exams.filter(x=>x.id!==id);saveDB();examsPage()}}
function marksEntry(){modal('Bulk Marks Entry',`<form id="marksForm"><div class="form-grid"><div><label>Exam</label><select name="exam_id">${db.exams.map(x=>`<option value="${x.id}">${esc(x.name)} — ${esc(x.class_name)}</option>`).join('')}</select></div><div><label>Subject</label><input name="subject" required></div><div><label>Max Marks</label><input name="max" type="number" value="100"></div></div><div id="markList" class="card" style="margin-top:12px"></div><div class="form-actions"><button class="btn primary">Save Marks</button></div></form>`);const render=()=>{const ex=db.exams.find(x=>x.id===document.querySelector('[name=exam_id]').value);const list=db.students.filter(s=>!ex?.class_name||s.class_name===ex.class_name);document.getElementById('markList').innerHTML=list.map(s=>`<div style="display:grid;grid-template-columns:1fr 120px;gap:8px;padding:6px;border-bottom:1px solid var(--line)"><span>${esc(s.name)}</span><input data-sid="${s.id}" type="number" min="0"></div>`).join('')||'<div class="empty">No students.</div>'};document.querySelector('[name=exam_id]').onchange=render;render();document.getElementById('marksForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));document.querySelectorAll('#markList input').forEach(i=>{if(i.value==='')return;db.marks.push({id:uid('mark'),exam_id:o.exam_id,student_id:i.dataset.sid,subject:o.subject,max:Number(o.max),score:Number(i.value),created_by:currentUser.id})});saveDB();closeModal();toast('Marks saved');examsPage()}}
function reportCardPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Report Card','Student result and printable report card',`<button class="btn light" onclick="openReportCard()">Open Report Card</button>`)+`<div class="card"><div class="empty">Select a student to generate the report card.</div></div>`}
function openReportCard(){modal('Report Card',`<select id="rcStu"><option value="">Select student</option>${db.students.map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.admission_no)}</option>`).join('')}</select><div id="rcOut" style="margin-top:12px"></div>`);document.getElementById('rcStu').onchange=e=>{const s=db.students.find(x=>x.id===e.target.value);const ms=db.marks.filter(m=>m.student_id===s?.id);document.getElementById('rcOut').innerHTML=s?`<div id="reportCard" style="border:1px solid #ccc;padding:22px"><div style="text-align:center"><img src="./logo.jpg" style="width:70px"><h2>${SCHOOL.name}</h2><b>DISE Code – ${SCHOOL.dise}</b><p>${SCHOOL.address}</p><h3>REPORT CARD</h3></div><p><b>Student:</b> ${esc(s.name)} &nbsp; <b>Admission:</b> ${esc(s.admission_no)} &nbsp; <b>Class:</b> ${esc(s.class_name)}-${esc(s.section)}</p>${table(ms.map(m=>`<tr><td>${esc(db.exams.find(e=>e.id===m.exam_id)?.name)}</td><td>${esc(m.subject)}</td><td>${m.score}</td><td>${m.max}</td></tr>`),['Exam','Subject','Marks','Max'])}</div><div class="form-actions"><button class="btn primary" onclick="print()">Print</button></div>`:''}}
function certificatesPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Certificates','Templates, auto-fill, numbering, preview and print',`<button class="btn primary" onclick="makeCertificate()">+ Create Certificate</button>`)+`<div class="card">${table(db.certificates.map(c=>{const s=db.students.find(x=>x.id===c.student_id)||{};return `<tr><td>${esc(c.number)}</td><td>${esc(s.name)}</td><td>${esc(c.type)}</td><td>${esc(c.date)}</td><td><button class="btn small light" onclick="printCertificate('${c.id}')">Preview/Print</button></td></tr>`}),['Certificate No.','Student','Type','Date','Action'])}</div>`}
function makeCertificate(){modal('Create Certificate',`<form id="certForm"><div class="form-grid"><div class="wide"><label>Student</label><select name="student_id">${db.students.map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.admission_no)}</option>`).join('')}</select></div><div><label>Type</label><input name="type" value="Bonafide Certificate"></div><div><label>Number</label><input name="number" value="CERT-${Date.now().toString().slice(-6)}"></div><div><label>Date</label><input type="date" name="date" value="${new Date().toISOString().slice(0,10)}"></div></div><div class="form-actions"><button class="btn primary">Create</button></div></form>`);document.getElementById('certForm').onsubmit=e=>{e.preventDefault();db.certificates.push({id:uid('cert'),...Object.fromEntries(new FormData(e.target))});saveDB();closeModal();certificatesPage()}}
function printCertificate(id){const c=db.certificates.find(x=>x.id===id),s=db.students.find(x=>x.id===c.student_id)||{};modal('Certificate Preview',`<div id="certificate" style="border:8px double #caa83a;padding:45px;text-align:center;min-height:500px"><img src="./logo.jpg" style="width:100px"><h2>${SCHOOL.name}</h2><div>DISE Code – ${SCHOOL.dise}</div><p>${SCHOOL.address}</p><h1>${esc(c.type)}</h1><p>This is to certify that <b>${esc(s.name)}</b>, Admission No. <b>${esc(s.admission_no)}</b>, Class <b>${esc(s.class_name)}-${esc(s.section)}</b> is a student of this school.</p><p>Certificate No.: ${esc(c.number)} &nbsp; Date: ${esc(c.date)}</p></div><div class="form-actions"><button class="btn primary" onclick="print()">Print</button></div>`)}
function idsPage(){const p=document.getElementById('page');p.innerHTML=pageHead('ID Cards','Portrait student and staff ID cards with photo/logo',`<button class="btn primary" onclick="idCard()">Create/Preview ID Card</button>`)+`<div class="card"><div class="empty">ID cards are generated from student/staff master records.</div></div>`}
function idCard(){modal('ID Card',`<select id="idWho"><option value="">Select Student</option>${db.students.map(s=>`<option value="s:${s.id}">${esc(s.name)} — ${esc(s.admission_no)}</option>`).join('')}<option disabled>— Staff —</option>${db.staff.map(s=>`<option value="t:${s.id}">${esc(s.name)} — ${esc(s.employee_id)}</option>`).join('')}</select><div id="idOut" style="margin-top:14px"></div>`);document.getElementById('idWho').onchange=e=>{const [t,id]=e.target.value.split(':');const x=(t==='s'?db.students:db.staff).find(z=>z.id===id);if(!x)return;document.getElementById('idOut').innerHTML=`<div id="idcard" style="width:320px;margin:auto;border:1px solid #ccc;border-radius:15px;overflow:hidden;text-align:center"><div style="background:#0b2148;color:#fff;padding:15px"><img src="./logo.jpg" style="width:65px;height:65px;object-fit:contain;background:#fff;border-radius:50%"><h3 style="margin:7px 0">${SCHOOL.name}</h3><small>DISE Code – ${SCHOOL.dise}</small></div><div style="padding:18px"><div style="width:90px;height:105px;border:1px solid #bbb;margin:auto"></div><h3>${esc(x.name)}</h3><p>${t==='s'?`Admission No.: ${esc(x.admission_no)}<br>Class: ${esc(x.class_name)}-${esc(x.section)}<br>Roll No.: ${esc(x.roll_no)}`:`Employee ID: ${esc(x.employee_id)}<br>${esc(x.designation)}`}</p></div></div><div class="form-actions"><button class="btn primary" onclick="print()">Print</button></div>`}}
function timetablePage(){const p=document.getElementById('page');p.innerHTML=pageHead('Timetable','Class, section, teacher, subject, day and period',`<button class="btn primary" onclick="addTimetable()">+ Add Period</button>`)+`<div class="card">${table(db.timetable.map(x=>`<tr><td>${esc(x.day)}</td><td>${esc(x.period)}</td><td>${esc(x.class_name)}-${esc(x.section)}</td><td>${esc(x.subject)}</td><td>${esc(x.teacher)}</td><td>${esc(x.room)}</td><td><button class="btn small danger" onclick="db.timetable=db.timetable.filter(a=>a.id!=='${x.id}');saveDB();timetablePage()">Delete</button></td></tr>`),['Day','Period','Class','Subject','Teacher','Room','Action'])}</div>`}
function addTimetable(){modal('Add Timetable Period',`<form id="ttForm"><div class="form-grid"><div><label>Day</label><select name="day"><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option></select></div><div><label>Period</label><input name="period" placeholder="1"></div><div><label>Class</label><input name="class_name"></div><div><label>Section</label><input name="section" value="A"></div><div><label>Subject</label><input name="subject"></div><div><label>Teacher</label><input name="teacher"></div><div><label>Room</label><input name="room"></div></div><div class="form-actions"><button class="btn primary">Save</button></div></form>`);document.getElementById('ttForm').onsubmit=e=>{e.preventDefault();db.timetable.push({id:uid('tt'),...Object.fromEntries(new FormData(e.target))});saveDB();closeModal();timetablePage()}}
function homeworkPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Homework / Assignment','Publish homework and assignments for student/parent portal',`<button class="btn primary" onclick="addHomework()">+ New Homework</button>`)+`<div class="card">${table(db.homework.map(h=>`<tr><td>${esc(h.date)}</td><td>${esc(h.class_name)}-${esc(h.section)}</td><td>${esc(h.subject)}</td><td>${esc(h.title)}</td><td>${esc(h.due_date)}</td><td>${h.published?'Published':'Draft'}</td></tr>`),['Date','Class','Subject','Title','Due Date','Status'])}</div>`}
function addHomework(){modal('New Homework / Assignment',`<form id="hwForm"><div class="form-grid"><div><label>Date</label><input type="date" name="date" value="${new Date().toISOString().slice(0,10)}"></div><div><label>Class</label><input name="class_name"></div><div><label>Section</label><input name="section" value="A"></div><div><label>Subject</label><input name="subject"></div><div class="wide"><label>Title</label><input name="title" required></div><div><label>Due Date</label><input type="date" name="due_date"></div><div><label>Published</label><select name="published"><option value="true">Yes</option><option value="false">No</option></select></div><div class="wide"><label>Description</label><textarea name="description" rows="3"></textarea></div></div><div class="form-actions"><button class="btn primary">Publish</button></div></form>`);document.getElementById('hwForm').onsubmit=e=>{e.preventDefault();db.homework.push({id:uid('hw'),...Object.fromEntries(new FormData(e.target))});saveDB();closeModal();homeworkPage()}}
function communicationPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Communication','Notices, class/student communication, SMS/WhatsApp-ready text',`<button class="btn primary" onclick="addNotice()">+ New Notice</button>`)+`<div class="card">${db.notices.map(n=>`<div class="notice"><b>${esc(n.title)}</b><div class="muted">${esc(n.date)} • ${esc(n.audience)}</div><p>${esc(n.body)}</p><button class="btn small light" onclick="navigator.clipboard?.writeText(${JSON.stringify(n.body)});toast('Text copied for SMS/WhatsApp')">Copy Text</button></div>`).join('')||'<div class="empty">No notices.</div>'}</div>`}
function addNotice(){modal('New Notice',`<form id="noticeForm"><div class="form-grid"><div class="wide"><label>Title</label><input name="title" required></div><div><label>Audience</label><select name="audience"><option>All</option><option>Class</option><option>Student</option><option>Parents</option></select></div><div><label>Date</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="wide"><label>Message</label><textarea name="body" rows="5" required></textarea></div></div><div class="form-actions"><button class="btn primary">Publish Notice</button></div></form>`);document.getElementById('noticeForm').onsubmit=e=>{e.preventDefault();db.notices.push({id:uid('notice'),...Object.fromEntries(new FormData(e.target))});saveDB();closeModal();communicationPage()}}
function parentsPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Parent Contacts','Parent/guardian contact directory',`<button class="btn primary" onclick="addParent()">+ Add Contact</button>`)+`<div class="card">${table(db.parents.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.relation)}</td><td>${esc(db.students.find(s=>s.id===x.student_id)?.name||'')}</td><td>${esc(x.mobile)}</td><td><button class="btn small danger" onclick="db.parents=db.parents.filter(a=>a.id!=='${x.id}');saveDB();parentsPage()">Delete</button></td></tr>`),['Parent','Relation','Student','Mobile','Action'])}</div>`}
function addParent(){modal('Parent Contact',`<form id="parForm"><div class="form-grid"><div><label>Name</label><input name="name" required></div><div><label>Relation</label><input name="relation" value="Father"></div><div class="wide"><label>Student</label><select name="student_id">${db.students.map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.admission_no)}</option>`).join('')}</select></div><div><label>Mobile</label><input name="mobile"></div></div><div class="form-actions"><button class="btn primary">Save</button></div></form>`);document.getElementById('parForm').onsubmit=e=>{e.preventDefault();db.parents.push({id:uid('par'),...Object.fromEntries(new FormData(e.target))});saveDB();closeModal();parentsPage()}}
function reportsPage(){const p=document.getElementById('page');const bal=feeBalanceAll();p.innerHTML=pageHead('Reports','Admin / Principal / Accountant only • operational + financial reports',`<button class="btn light" onclick="print()">Print</button>`)+`<div class="grid"><div class="stat">Students<b>${db.students.length}</b></div><div class="stat">Staff<b>${db.staff.length}</b></div><div class="stat">Attendance<b>${db.attendance.length}</b></div><div class="stat">Fees Paid<b>₹${money(bal.paid)}</b></div></div><div class="card"><h3>Class Strength</h3>${table([...new Set(db.students.map(s=>s.class_name).filter(Boolean))].map(c=>`<tr><td>${esc(c)}</td><td>${db.students.filter(s=>s.class_name===c).length}</td><td>${db.students.filter(s=>s.class_name===c&&s.status!=='left').length}</td></tr>`),['Class','Total','Active'])}</div>`}
function promotionPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Promotion','Session-to-session promote, hold, repeat and left',`<button class="btn primary" onclick="promoteAll()">Promotion Tool</button>`)+`<div class="card">${table(db.promotions.map(x=>{const s=db.students.find(z=>z.id===x.student_id)||{};return `<tr><td>${esc(s.name)}</td><td>${esc(x.from)}</td><td>${esc(x.to)}</td><td>${esc(x.result)}</td></tr>`}),['Student','From','To','Status'])}</div>`}
function promoteAll(){modal('Promotion',`<form id="proForm"><div class="form-grid"><div><label>From Session</label><input name="from" value="${esc(db.settings.session)}"></div><div><label>To Session</label><input name="to"></div><div><label>Class From</label><input name="fromClass"></div><div><label>Class To</label><input name="toClass"></div><div><label>Result</label><select name="result"><option>Promote</option><option>Hold</option><option>Repeat</option><option>Left</option></select></div></div><div class="form-actions"><button class="btn primary">Apply to Matching Students</button></div></form>`);document.getElementById('proForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));db.students.filter(s=>s.class_name===o.fromClass).forEach(s=>{db.promotions.push({id:uid('pro'),student_id:s.id,from:o.from,to:o.to,result:o.result});if(o.result==='Left')s.status='left';else if(o.result==='Promote')s.class_name=o.toClass});saveDB();closeModal();promotionPage()}}
function usersPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Users & Permissions','School accounts, roles, reset/disable credentials',`<button class="btn primary" onclick="addUser()">+ Add User</button>`)+`<div class="card">${table(db.users.map(u=>`<tr><td>${esc(u.username)}</td><td>${esc(u.name)}</td><td>${esc(ROLES[u.role]||u.role)}</td><td>${u.active?'Active':'Disabled'}</td><td><button class="btn small light" onclick="resetUser('${u.id}')">Reset</button> <button class="btn small danger" onclick="toggleUser('${u.id}')">${u.active?'Disable':'Enable'}</button></td></tr>`),['Login ID','Name','Role','Status','Action'])}</div>`}
function addUser(){modal('Add User',`<form id="userForm"><div class="form-grid"><div><label>Login ID</label><input name="username" required></div><div><label>Name</label><input name="name" required></div><div><label>Password</label><input name="password" value="1234" required></div><div><label>Role</label><select name="role"><option>admin</option><option>principal</option><option>accountant</option><option>office</option><option>teacher</option><option>parent</option></select></div></div><div class="form-actions"><button class="btn primary">Create</button></div></form>`);document.getElementById('userForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(db.users.some(u=>u.username===o.username))return toast('Login ID exists');db.users.push({id:uid('usr'),...o,active:true});saveDB();closeModal();usersPage()}}
function resetUser(id){const u=db.users.find(x=>x.id===id);if(!u)return;u.password='1234';saveDB();toast('Password reset to 1234')}
function toggleUser(id){const u=db.users.find(x=>x.id===id);if(u){u.active=!u.active;saveDB();usersPage()}}
function cloudPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Central Database','Supabase central database configuration; end users do not need a separate cloud login',`<button class="btn primary" onclick="testCloud()">Test Connection</button>`)+`<div class="card"><h3>Cloud Configuration</h3><p class="muted">Enter the school Supabase project URL and publishable/anon key once on the administrator device. These settings are local configuration, not a second end-user login.</p><div class="form-grid"><div class="wide"><label>Supabase Project URL</label><input id="cloudUrl" value="${esc(db.cloud.url)}" placeholder="https://xxxxx.supabase.co"></div><div class="wide"><label>Publishable / Anon Key</label><input id="cloudKey" type="password" value="${esc(db.cloud.key)}"></div></div><div class="form-actions"><button class="btn primary" onclick="saveCloud()">Save Configuration</button><button class="btn light" onclick="downloadSchema()">Database Schema</button></div><div id="cloudMsg" class="hint">Status: ${esc(db.cloud.status||'Not configured')}</div></div><div class="card"><h3>Sync Architecture</h3><p>Normalized records use separate tables. Fees use immutable transactions + allocations + void/audit records. The client never overwrites a complete shared fee JSON object.</p></div>`}
function saveCloud(){db.cloud.url=document.getElementById('cloudUrl').value.trim().replace(/\/$/,'');db.cloud.key=document.getElementById('cloudKey').value.trim();db.cloud.status=db.cloud.url&&db.cloud.key?'Configured':'Not configured';saveDB();toast('Cloud configuration saved');cloudPage()}
async function testCloud(){if(!db.cloud.url||!db.cloud.key)return toast('Enter Supabase URL and key first');try{const r=await fetch(db.cloud.url+'/rest/v1/',{headers:{apikey:db.cloud.key,Authorization:'Bearer '+db.cloud.key}});db.cloud.status=r.ok?'Connected':'Connection responded '+r.status;db.cloud.lastSync=new Date().toISOString();saveDB();cloudPage()}catch(e){db.cloud.status='Connection failed';saveDB();cloudPage()}}
function downloadSchema(){const a=document.createElement('a');a.href='supabase-schema.sql';a.download='supabase-schema.sql';a.click()}
function backupPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Backup & Restore','Full backup, safety backup and restore',`<button class="btn primary" onclick="backup()">Download Full Backup</button><label class="btn light">Restore Backup<input id="restore" type="file" accept=".json" hidden></label>`)+`<div class="card"><h3>Safety rule</h3><p>Restore creates a safety copy in memory before replacing the local database. Financial void/audit history is retained in the backup.</p></div>`;document.getElementById('restore').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const incoming=JSON.parse(r.result);if(!confirm('Restore this backup? Current data will be replaced.'))return;localStorage.setItem(DBKEY,JSON.stringify(db));db=incoming;saveDB();toast('Backup restored');render()}catch{toast('Invalid backup')}};r.readAsText(f)}}
function backup(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download='Nikhat_ERP_Full_Backup_'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href);toast('Full backup downloaded')}
function healthPage(){const p=document.getElementById('page');const checks=[['Local database',!!db],['Students data',Array.isArray(db.students)],['Fee transaction model',Array.isArray(db.fees)],['Audit log',Array.isArray(db.audit)],['PWA service worker','serviceWorker' in navigator],['Cloud configuration',!!(db.cloud.url&&db.cloud.key)],['Cloud status',db.cloud.status==='Connected']];p.innerHTML=pageHead('System Health','Data integrity and PWA/cloud status')+`<div class="card">${checks.map(c=>`<div style="display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid var(--line)"><span>${esc(c[0])}</span><span class="pill ${c[1]?'ok':'danger'}">${c[1]?'PASS':'INFO'}</span></div>`).join('')}</div><div class="card"><b>Counts:</b> Students ${db.students.length} • Staff ${db.staff.length} • Attendance ${db.attendance.length} • Marks ${db.marks.length} • Fee transactions ${db.fees.length}</div>`}
function settingsPage(){const p=document.getElementById('page');p.innerHTML=pageHead('Settings','Central school identity and academic settings',`<button class="btn primary" onclick="saveSettings()">Save Settings</button>`)+`<div class="card"><div class="form-grid"><div class="wide"><label>School Name</label><input id="setName" value="${esc(SCHOOL.name)}"></div><div><label>DISE Code</label><input id="setDise" value="${esc(SCHOOL.dise)}"></div><div class="wide"><label>Address</label><textarea id="setAddress" rows="2">${esc(SCHOOL.address)}</textarea></div><div><label>Academic Session</label><input id="setSession" value="${esc(db.settings.session)}"></div></div><p class="muted">Logo is supplied by the school and stored as the official branding asset in this build.</p></div>`}
function saveSettings(){const n=document.getElementById('setName').value.trim(),d=document.getElementById('setDise').value.trim(),a=document.getElementById('setAddress').value.trim();SCHOOL.name=n||SCHOOL.name;SCHOOL.dise=d||SCHOOL.dise;SCHOOL.address=a||SCHOOL.address;db.settings.session=document.getElementById('setSession').value.trim()||db.settings.session;db.settings.school=clone(SCHOOL);saveDB();toast('Settings saved');settingsPage()}
function portal(){const linked=currentUser.student_id||db.students[0]?.id;const s=db.students.find(x=>x.id===linked)||db.students[0];const b=s?feeBalance(s.id):{previous:0,current:0,due:0,paid:0};const at=s?db.attendance.filter(a=>a.student_id===s.id):[];const ms=s?db.marks.filter(m=>m.student_id===s.id):[];const hw=db.homework.filter(h=>h.published==='true'||h.published===true);document.getElementById('app').innerHTML=`<div class="shell"><header class="top">${schoolHeader('Student & Parent Portal')}<button class="btn gold small" onclick="logout()">Logout</button></header><main class="main portal"><section class="portal-head"><img src="./logo.jpg"><div><span class="tag">Student & Parent Portal</span><h2 style="margin:6px 0">${esc(s?.name||'Student')}</h2><div class="muted">${esc(s?.class_name||'')} ${esc(s?.section||'')} • ${esc(s?.admission_no||'')}</div></div></section><div class="portal-grid"><div class="portal-card"><h3>Attendance</h3><p>Present ${at.filter(x=>x.status==='Present').length} • Absent ${at.filter(x=>x.status==='Absent').length} • Leave ${at.filter(x=>x.status==='Leave').length}</p></div><div class="portal-card"><h3>Homework</h3><p>${hw.length} published item(s)</p></div><div class="portal-card"><h3>Marks / Result</h3><p>${ms.length} mark entries available</p></div><div class="portal-card"><h3>Report Card</h3><button class="btn small light" onclick="openReportCard()">View Report Card</button></div><div class="portal-card"><h3>Fees</h3><p>Previous Due: ₹${money(b.previous)}<br>Current Due: ₹${money(b.current)}<br><b>Total Due: ₹${money(b.due)}</b><br>Paid: ₹${money(b.paid)}</p><button class="btn small light" onclick="studentPortalFees('${s?.id||''}')">Fee History</button></div><div class="portal-card"><h3>Notices</h3>${db.notices.slice(-4).reverse().map(n=>`<div class="notice"><b>${esc(n.title)}</b><br><small>${esc(n.date)}</small></div>`).join('')||'<p class="muted">No notices.</p>'}</div></div></main></div>`}
function studentPortalFees(sid){const tx=db.fees.filter(t=>t.student_id===sid&&t.status!=='void');modal('My Fee History',`${table(tx.map(t=>`<tr><td>${esc(t.date)}</td><td>${esc(t.receipt_no)}</td><td>₹${money(t.amount)}</td><td>${esc(t.mode)}</td><td><button class="btn small light" onclick="printReceipt('${t.id}')">Receipt</button></td></tr>`),['Date','Receipt','Amount','Mode','Receipt'])}`)}
function audit(entity,id,oldData,newData,action){db.audit.push({id:uid('audit'),entity,entity_id:id,action,old_data:clone(oldData),new_data:clone(newData),actor:currentUser?.id||'system',created_at:new Date().toISOString()})}
function updateCloudStatus(){/* Deliberately no automatic destructive cloud writes. Cloud layer is isolated until server schema/RLS is configured. */}
// Make initial built-in users visible to the user manager without forcing them into login storage.
if(!Array.isArray(db.users))db.users=[];
if(!db.users.length){db.users=[{id:'usr_admin',username:'admin',password:'1234',name:'Administrator',role:'admin',active:true},{id:'usr_principal',username:'principal',password:'1234',name:'Principal',role:'principal',active:true},{id:'usr_accountant',username:'accountant',password:'1234',name:'Accountant',role:'accountant',active:true},{id:'usr_office',username:'office',password:'1234',name:'Office Assistant',role:'office',active:true},{id:'usr_teacher',username:'teacher',password:'1234',name:'Teacher',role:'teacher',active:true},{id:'usr_student',username:'student',password:'1234',name:'Student/Parent',role:'parent',active:true}];saveDB()}
// Ensure saved school settings remain authoritative for the current session.
if(db.settings?.school){SCHOOL.name=db.settings.school.name||SCHOOL.name;SCHOOL.dise=db.settings.school.dise||SCHOOL.dise;SCHOOL.address=db.settings.school.address||SCHOOL.address}
render();
